{"adam.cl.code-snippets":"{
  // Place your global snippets here. Each snippet is defined under a snippet name and has a scope, prefix, body and
  // description. Add comma separated ids of the languages where the snippet is applicable in the scope field. If scope
  // is left empty or omitted, the snippet gets applied to all languages. The prefix is what is
  // used to trigger the snippet and the body will be expanded and inserted. Possible variables are:
  // $1, $2 for tab stops, $0 for the final cursor position, and ${1:label}, ${2:another} for placeholders.
  // Placeholders with the same ids are connected.
  // Example:

  "Print to console": {
    "scope": "javascript,typescript,javascriptreact,typescriptreact",
    "prefix": "cl",
    "body": ["className='$1'"],
    "description": "Creates a classname"
  },

  "JSX/TSX arrow function": {
    "scope": "javascriptreact, typescriptreact",
    "prefix": "arrow",
    "body": ["const $1 = () => {return (<><div>$2</div></>);};export default  $1;"],
    "description": "create new arrow function"
  },

  "Next.js page.tsx": {
    "scope": "javascriptreact, typescriptreact",
    "prefix": "page",
    "body": [
      "export default async function $1() {return (<><div>$1</div></>);}"
    ],
  },

  "UseEffect" : {
    "scope": "javascriptreact, typescriptreact",
    "prefix": "usee",
    "body": [
      "useEffect(() => {",
      "  $1",
      "}, [$2]);"
    ],
    "description": "useEffect"
  },

  "UseState": {
    "scope": "javascriptreact,typescriptreact",
    "prefix": "useS",
    "body": [
      "const [$1, set${1/(.)/${1:/capitalize}/}] = useState($2);"
    ],
    "description": "useState hook"
  }

}
","javascript.json":""}
